document.addEventListener('DOMContentLoaded', () => {
  const items = document.querySelectorAll('.reveal-up');

  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.12, rootMargin: '0px 0px -8% 0px' });

    items.forEach((item) => observer.observe(item));
  } else {
    items.forEach((item) => item.classList.add('is-visible'));
  }

  const year = document.getElementById('year');
  if (year) year.textContent = new Date().getFullYear();
});


(function(){
  const header=document.querySelector('.site-header');
  const hero=document.querySelector('.hero-stable');
  if(!header||!hero)return;
  const update=()=>header.classList.toggle('is-visible',window.scrollY>Math.max(120,hero.offsetHeight*.78));
  update();
  window.addEventListener('scroll',update,{passive:true});
  window.addEventListener('resize',update);
})();


/* SHOW UP interactive product demo — scoped to [data-su-demo] */
(function(){
  const demo=document.querySelector('[data-su-demo]');
  if(!demo)return;
  const stage=demo.querySelector('.su-demo-stage');
  const steps=[...demo.querySelectorAll('.su-demo-step')];
  const screens=[...demo.querySelectorAll('.su-demo-screen')];
  const counter=demo.querySelector('.su-demo-counter');
  const progress=demo.querySelector('.su-demo-progress span');
  const fileInput=demo.querySelector('#su-demo-file');
  const drop=demo.querySelector('.su-demo-drop');
  const flying=demo.querySelector('[data-demo-thumbs]');
  const screening=demo.querySelector('[data-screening-grid]');
  const nine=demo.querySelector('[data-nine-grid]');
  const edit=demo.querySelector('[data-edit-grid]');
  const candidates=demo.querySelector('[data-candidate-row]');
  const replacePrompt=demo.querySelector('[data-replace-prompt]');
  const replaceQuestion=demo.querySelector('[data-replace-question]');
  const reviewKeep=demo.querySelector('[data-review-keep]');
  const reviewReplace=demo.querySelector('[data-review-replace]');
  const shareGrid=demo.querySelector('[data-share-grid]');
  const shareButton=demo.querySelector('[data-share-button]');
  const shareSheet=demo.querySelector('[data-share-sheet]');
  const personaImgs=[...document.querySelectorAll('.persona-card img')].map(i=>i.src).filter(Boolean);
  const fixedPersonaSet=[
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,'
  ];
  let hasUserFiles=false;
  let sources=[]; let current=0; let timer=null; let candidateIndex=0; let reviewResolved=false;
  const roles=['COVER','CLOSE-UP','PRODUCT','USING IT','LIFESTYLE','DETAIL','HUMAN','CONTEXT','CLOSING'];
  const reasons=['BEST','Duplicate','Blur','BEST','Out of focus','BEST','Eyes closed','BEST','Duplicate','BEST','Blur','BEST'];

  function baseSources(){
    const arr=personaImgs.length?personaImgs:[];
    if(!arr.length)return [];
    return Array.from({length:18},(_,i)=>arr[i%arr.length]);
  }
  sources=baseSources();

  function img(src,cls=''){
    const el=document.createElement('img'); el.src=src; if(cls)el.className=cls; el.alt=''; return el;
  }
  function renderFlying(){
    flying.innerHTML=''; sources.slice(0,7).forEach((src,i)=>{const el=img(src);el.style.animationDelay=(i*.07)+'s';flying.appendChild(el);});
  }
  function renderScreening(){
    screening.innerHTML=''; sources.slice(0,12).forEach((src,i)=>{const tile=document.createElement('div');tile.className='su-demo-tile '+(reasons[i]==='BEST'?'is-best':'is-rejected');if(reasons[i]!=='BEST')tile.dataset.reason=reasons[i];tile.appendChild(img(src));screening.appendChild(tile);});
  }
  function makeSetTile(src,i,editable=false){
    const tile=document.createElement('div'); tile.className='su-demo-set-tile'; tile.dataset.index=i;
    tile.appendChild(img(src));
    if(!editable){const em=document.createElement('em');em.textContent=roles[i]||'';tile.appendChild(em);}
    return tile;
  }
  function setSources(){
    if(!hasUserFiles && fixedPersonaSet.length===9)return [...fixedPersonaSet];
    return Array.from({length:9},(_,i)=>sources[(i*2+1)%Math.max(sources.length,1)]||'');
  }
  let chosen=setSources();
  function renderNine(){nine.innerHTML='';chosen.forEach((src,i)=>{const t=makeSetTile(src,i,false);t.style.animationDelay=(i*.045)+'s';nine.appendChild(t);});}
  function resetReplacePrompt(){
    reviewResolved=false;
    if(replacePrompt){replacePrompt.classList.remove('is-done');replacePrompt.style.display='block';}
    if(replaceQuestion)replaceQuestion.textContent='Replace?';
  }
  function renderEdit(){
    edit.innerHTML='';
    chosen.forEach((src,i)=>{
      const t=makeSetTile(src,i,true);
      if(!reviewResolved && (i===1||i===3)){
        t.classList.add('is-selected');
        const check=document.createElement('span');check.className='su-demo-select-check';check.textContent='✓';t.appendChild(check);
      }
      edit.appendChild(t);
    });
    candidates.innerHTML=''; const pool=sources.slice(9,12).concat(sources.slice(0,3));pool.slice(0,3).forEach((src,i)=>{const im=img(src);im.addEventListener('click',()=>replaceAt(i===0?1:3,src));candidates.appendChild(im);});
  }
  function replaceAt(index,src){
    candidateIndex=index===3?1:0;
    const pool=sources.slice(9).concat(sources);
    chosen[index]=src||pool[(index+candidateIndex+2)%pool.length];
    renderEdit(); renderShare();
  }
  function renderShare(){shareGrid.innerHTML='';chosen.forEach((src,i)=>shareGrid.appendChild(makeSetTile(src,i,true)));}
  function renderAll(){chosen=setSources();renderFlying();renderScreening();renderNine();renderEdit();renderShare();}

  function go(n,user=false){
    current=(n+screens.length)%screens.length;
    steps.forEach((b,i)=>b.classList.toggle('is-active',i===current));
    screens.forEach((s,i)=>s.classList.toggle('is-active',i===current));
    counter.textContent=String(current+1).padStart(2,'0')+' / 05';
    progress.style.width=((current+1)*20)+'%';
    if(current===0)renderFlying();
    if(current===1)renderScreening();
    if(current===2)renderNine();
    if(current===3){resetReplacePrompt();renderEdit();}
    if(current===4)renderShare();
    if(user){stopAuto();startAuto(6500);}
  }
  steps.forEach((b,i)=>b.addEventListener('click',()=>go(i,true)));

  function takeFiles(files){
    const imgs=[...files].filter(f=>f.type.startsWith('image/')).slice(0,100);
    if(!imgs.length)return;
    hasUserFiles=true;
    sources.forEach(s=>{if(s.startsWith('blob:'))URL.revokeObjectURL(s);});
    sources=imgs.map(f=>URL.createObjectURL(f));
    while(sources.length<12)sources.push(...sources.slice(0,Math.min(sources.length,12-sources.length)));
    renderAll(); go(1,true);
  }
  if(fileInput)fileInput.addEventListener('change',e=>takeFiles(e.target.files||[]));
  ['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('is-drag');}));
  ['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('is-drag');}));
  drop.addEventListener('drop',e=>takeFiles(e.dataTransfer.files||[]));
  if(reviewKeep)reviewKeep.addEventListener('click',()=>{
    reviewResolved=true;
    renderEdit();
    if(replacePrompt)replacePrompt.classList.add('is-done');
    if(replaceQuestion)replaceQuestion.textContent='Keep selected ✓';
  });
  if(reviewReplace)reviewReplace.addEventListener('click',()=>{
    const pool=sources.slice(9).concat(sources);
    if(pool.length){chosen[1]=pool[2%pool.length]||chosen[1];chosen[3]=pool[5%pool.length]||chosen[3];}
    reviewResolved=true;
    renderEdit();renderShare();
    if(replacePrompt)replacePrompt.classList.add('is-done');
    if(replaceQuestion)replaceQuestion.textContent='Replaced ✓';
  });
  shareButton.addEventListener('click',()=>shareSheet.classList.toggle('is-open'));
  shareSheet.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{b.textContent='Ready to share ✓';setTimeout(()=>shareSheet.classList.remove('is-open'),900);}));

  function stopAuto(){if(timer){clearInterval(timer);timer=null;}}
  function startAuto(delay=3600){stopAuto();timer=setInterval(()=>go(current+1),delay);}
  const io=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)startAuto();else stopAuto();});},{threshold:.25});
  io.observe(demo);
  demo.addEventListener('mouseenter',stopAuto);
  demo.addEventListener('mouseleave',()=>startAuto(5000));
  renderAll(); go(0);
})();
